INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine IPv4-Adresse immer genau 32 Bits lang?', 2, '[{"text": "Ja", "correct": true, "because": "Standardlänge für IPv4"}, {"text": "Nein", "correct": false, "because": "Keine Variation möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits nutze ich für die Darstellung von 192 in Binärcode?', 3, '[{"text": "8", "correct": true, "because": "Ein Oktett hat 8 Bits"}, {"text": "4", "correct": false, "because": "Zu wenig für 192"}, {"text": "16", "correct": false, "because": "Zu viel für ein Oktett"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen stimmen? a) Ein Oktett hat 8 Bits. b) IPv4 nutzt 64 Bits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv4 hat 32 Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Binärdarstellung einer Adresse?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert die Struktur"}, {"text": "Oktetttrennung", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255 in Binärcode 11111111 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Alle 8 Bits auf 1"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zahl entspricht 11000000 in Dezimal?', 3, '[{"text": "192", "correct": true, "because": "128 + 64 = 192"}, {"text": "64", "correct": false, "because": "Nur eine Position"}, {"text": "255", "correct": false, "because": "Alle Bits wären 1"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine IPv4-Adresse?', 5, '[{"text": "32 Bits", "correct": true, "because": "Feste Länge"}, {"text": "4 Oktette", "correct": true, "because": "Dezimale Struktur"}, {"text": "Hexadezimal", "correct": false, "because": "IPv6-spezifisch"}, {"text": "128 Bits", "correct": false, "because": "IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) IPv4 hat 32 Bits. b) Jedes Oktett hat 16 Bits. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oktett hat 8 Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Adresse binär darzustellen?', 4, '[{"text": "Bitfolge", "correct": false, "because": "Kern der Darstellung"}, {"text": "Oktettstruktur", "correct": false, "because": "Definiert Aufbau"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Besteht eine Adresse aus 4 Bytes?', 2, '[{"text": "Ja", "correct": true, "because": "1 Byte = 8 Bits, 4x8 = 32"}, {"text": "Nein", "correct": false, "because": "Struktur passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte kann ein Oktett annehmen?', 4, '[{"text": "0-255", "correct": true, "because": "8 Bits erlauben 256 Werte"}, {"text": "0-127", "correct": false, "because": "Nur halber Bereich"}, {"text": "1-100", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 32 Bits nur für große Netze reichen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzt durch Adressraum"}, {"text": "Ja", "correct": false, "because": "IPv4 ist limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Umrechnung in Binärcode?', 3, '[{"text": "Bitpositionen", "correct": true, "because": "Bestimmen den Wert"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Rundung", "correct": false, "because": "Keine Dezimalwerte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 32 Bits sind 4 Oktette. b) IPv4 nutzt Dezimalzahlen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Struktur und Darstellung"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Binärdarstellung?', 5, '[{"text": "Netzwerkberechnung", "correct": true, "because": "Ermöglicht Subnetting"}, {"text": "Genauigkeit", "correct": true, "because": "Exakte Bitwerte"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Nicht relevant"}, {"text": "Einfache Lesbarkeit", "correct": false, "because": "Dezimal ist lesbarer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Struktur unwichtig?', 3, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert die Adresse"}, {"text": "Oktetttrennung", "correct": false, "because": "Strukturierte Darstellung"}, {"text": "Schriftart", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind 32 Bits auch in IPv6 Standard?', 3, '[{"text": "Nein", "correct": true, "because": "IPv6 hat 128 Bits"}, {"text": "Ja", "correct": false, "because": "Falsche Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 128 in Binärcode 10000000 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Erste Bitposition"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zahl ist 11110000 in Dezimal?', 4, '[{"text": "240", "correct": true, "because": "128 + 64 + 32 + 16"}, {"text": "15", "correct": false, "because": "Nur letzte 4 Bits"}, {"text": "192", "correct": false, "because": "Nur erste 2 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft hat 0.0.0.0?', 3, '[{"text": "Alle Bits sind 0", "correct": true, "because": "Binär 00000000 pro Oktett"}, {"text": "Nur für Broadcast", "correct": false, "because": "255.255.255.255 ist Broadcast"}, {"text": "64 Bits lang", "correct": false, "because": "IPv4 hat 32 Bits"}]');
